systemctl start netlabs-imagenes
mkdir -p /srv/tienda/html /srv/antigua
echo '<h1>Tienda online</h1>' > /srv/tienda/html/index.html
echo '<h1>Tienda antigua (cerrada)</h1>' > /srv/antigua/index.html
cat > /etc/systemd/system/antigua-tienda.service <<'EOF'
[Unit]
Description=Tienda antigua (servidor Python)
After=network.target

[Service]
ExecStart=/usr/bin/python3 -m http.server 8080 --directory /srv/antigua
Restart=on-failure

[Install]
WantedBy=multi-user.target
EOF
cat > /etc/systemd/system/container-tienda.service <<'EOF'
# container-tienda.service
# autogenerated by Podman 4.3.1

[Unit]
Description=Podman container-tienda.service
Documentation=man:podman-generate-systemd(1)
Wants=network-online.target
After=network-online.target
RequiresMountsFor=%t/containers

[Service]
Environment=PODMAN_SYSTEMD_UNIT=%n
Restart=no
TimeoutStopSec=70
ExecStartPre=/bin/rm \
	-f %t/%n.ctr-id
ExecStart=/usr/bin/podman run \
	--cidfile=%t/%n.ctr-id \
	--cgroups=no-conmon \
	--rm \
	--sdnotify=conmon \
	-d \
	--replace \
	-q \
	--name tienda \
	--read-only \
	-p 8080:80 \
	-v /srv/tienda/htm:/usr/share/nginx/html:ro nginx:1.27-alpine
ExecStop=/usr/bin/podman stop \
	--ignore -t 10 \
	--cidfile=%t/%n.ctr-id
ExecStopPost=/usr/bin/podman rm \
	-f \
	--ignore -t 10 \
	--cidfile=%t/%n.ctr-id
Type=notify
NotifyAccess=all

[Install]
WantedBy=default.target
EOF
systemctl daemon-reload
systemctl enable -q --now antigua-tienda
systemctl enable -q container-tienda
systemctl start container-tienda 2>/dev/null || true
